command:
$ErrorActionPreference="Stop"
Set-Location $env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="aa61e28cb5f3a12cd90f59f022da4b6111ce9e6b"
$branch="work/search-v3-indexed-filename-20261008"
git fetch origin --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main changed"}
$ref="refs/remotes/origin/"+$branch
git show-ref --verify --quiet $ref
if($LASTEXITCODE -ne 0){throw "work ref missing"}
if((& git rev-parse $ref).Trim() -ne $main){throw "branch differs from main"}
git merge-base --is-ancestor $ref refs/remotes/origin/main
if($LASTEXITCODE -ne 0){throw "not merged"}
git push origin --delete $branch
if($LASTEXITCODE -ne 0){throw "delete failed"}
git fetch origin --no-tags --prune
if($LASTEXITCODE -ne 0){throw "post-fetch failed"}
git show-ref --verify --quiet $ref
if($LASTEXITCODE -eq 0){throw "branch remains"}
Write-Host "SEARCH_V3_INDEXED_BRANCH_CLEANUP=PASS"
